```cuda
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cuda_runtime.h>

__device__ __forceinline__ uint32_t smem_u32(void* p) {
  uint32_t r;
  asm volatile("{ .reg .u64 u; cvta.to.shared.u64 u, %1; cvt.u32.u64 %0, u; }"
               : "=r"(r) : "l"(p));
  return r;
}
__device__ __forceinline__ uint32_t ctarank() {
  uint32_t r; asm volatile("mov.u32 %0, %%cluster_ctarank;" : "=r"(r)); return r;
}
__device__ __forceinline__ void cluster_sync() {
  asm volatile("barrier.cluster.arrive.aligned;" ::: "memory");
  asm volatile("barrier.cluster.wait.aligned;"   ::: "memory");
}

// delay_cta: which CTA of the pair is delayed (0 = leader, 1 = follower, 2 = neither)
// mode: 0 = baseline
//       1 = barrier.cluster before alloc
//       2 = barrier.cluster after alloc (before relinquish)
//       6 = barrier.cluster immediately before dealloc
extern "C" __global__ void __cluster_dims__(2, 1, 1)
repro(uint32_t* out, uint32_t delay_cta, uint32_t spin, uint32_t mode) {
  __shared__ uint32_t tmem_addr;
  uint32_t rank = ctarank();
  uint32_t warp = threadIdx.x >> 5;
  if (threadIdx.x == 0) tmem_addr = 0;
  __syncthreads();

  if (rank == delay_cta) { for (uint32_t i = 0; i < spin; i++) __nanosleep(1000); }

  if (mode == 1) cluster_sync();

  if (warp == 0) {
    uint32_t dst = smem_u32(&tmem_addr);
    asm volatile("tcgen05.alloc.cta_group::2.sync.aligned.shared::cta.b32 [%0], %1;"
                 :: "r"(dst), "r"(512) : "memory");
  }
  __syncthreads();

  if (mode == 2) cluster_sync();

  if (warp == 0) {
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::2.sync.aligned;" ::: "memory");
  }
  __syncthreads();
  if (threadIdx.x == 0) out[rank] = tmem_addr;
  __syncthreads();

  if (mode == 6) cluster_sync();

  if (warp == 0) {
    asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;"
                 :: "r"(tmem_addr), "r"(512) : "memory");
  }
}

int main(int argc, char** argv) {
  uint32_t dc = (argc > 1) ? atoi(argv[1]) : 1;      // delay follower by default
  uint32_t sp = (argc > 2) ? atoi(argv[2]) : 5000;
  uint32_t md = (argc > 3) ? atoi(argv[3]) : 0;

  uint32_t* d; cudaMalloc(&d, 4096);
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(2, 1, 1);
  cfg.blockDim = dim3(128, 1, 1);
  cudaLaunchAttribute a[1];
  a[0].id = cudaLaunchAttributeClusterDimension;
  a[0].val.clusterDim.x = 2; a[0].val.clusterDim.y = 1; a[0].val.clusterDim.z = 1;
  cfg.attrs = a; cfg.numAttrs = 1;

  if (cudaLaunchKernelEx(&cfg, repro, d, dc, sp, md) != cudaSuccess) {
    printf("launch failed\n"); return 2;
  }
  cudaError_t e = cudaDeviceSynchronize();
  printf("delay_cta=%u spin=%u mode=%u => %s\n", dc, sp, md, cudaGetErrorString(e));
  return (e == cudaSuccess) ? 0 : 1;
}
```

Build and run:

```bash
nvcc -gencode arch=compute_103a,code=sm_103a -o repro repro.cu
./repro 1 5000 0    # follower delayed, baseline    -> unspecified launch failure
./repro 0 5000 0    # leader   delayed, baseline    -> no error
./repro 1 5000 6    # follower delayed, barrier     -> no error
```

## Precondition audit

`Allocator2Sm::allocate()` (`include/cute/arch/tmem_allocator_sm100.hpp`):

| Documented `@pre` | Reproducer |
| --- | --- |
| Must be issued by a single fully active warp of the CTA | warp 0, all 32 lanes active |
| Must never be issued by more than one warp at the same time | only warp 0 issues |
| For repeated allocations, the same warp must be used | only one allocation |
| The 2 warps from participating CTAs have the same logical warp ID | warp 0 in both CTAs |

Plus the body text: *"Both CTAs must provide the exact same `dst_ptr` for correctness."* —
both CTAs take `cvta.to.shared` of the same static `__shared__` variable, so the CTA-local
offset is identical.

`Allocator2Sm::free()` (`tcgen05.dealloc`) documents three `@pre`: single fully active warp,
never more than one warp at a time, and the 2 warps from participating CTAs have the same
logical warp ID. All satisfied.

Notably, `free()` documents **no** requirement that the peer CTA's allocation must have
completed first — while its `@pre` referring to "the 2 warps from participating CTAs" does
imply `dealloc` is itself a CTA-pair collective.

## Results

### Asymmetry: only a late *follower* breaks

| Delayed CTA | Delay position | Result |
| --- | --- | --- |
| leader (rank 0) | before `alloc` | no error (tested up to `spin=50000`) |
| **follower (rank 1)** | **before `alloc`** | **`unspecified launch failure`** |
| follower (rank 1) | *after* `alloc` | no error |

The threshold is very low: `spin=0` passes, `spin=10` (~10 µs) fails 100%.

### Randomized ablation (N=25 per arm, run order shuffled, 100 runs total)

| Variant | Failures |
| --- | --- |
| baseline | **25/25 (100%)** |

### 🚀 Feature Description and Motivation

Add community-maintained AIBrix deployment samples for the Moore Threads MTT S5000 GPU and MUSA software stack.

AIBrix already supports vLLM and SGLang as inference engines. Providing small, reproducible hardware-specific samples would make it easier for MTT S5000 users to validate these engines with AIBrix Gateway, StormService, engine-aware metrics, and Prefill/Decode routing without requiring a large accelerator cluster.

### Use Case

An AIBrix user has a Kubernetes cluster containing Moore Threads MTT S5000 GPUs. The Moore Threads device plugin exposes the devices as:

```yaml
mthreads.com/gpu
```

Every sample should use a small model, initially `Qwen3-8B` or another model of comparable or smaller size, and require no more than two MTT S5000 GPUs in total:

| Engine | Deployment mode | Initial model and topology |
|---|---|---|
| vLLM | Colocated | Qwen3-8B, one replica, TP=1, one GPU |
| vLLM | P/D disaggregated | Qwen3-8B, Prefill TP=1 + Decode TP=1, two GPUs total |
| SGLang | Colocated | Qwen3-8B, one replica, TP=1, one GPU |
| SGLang | P/D disaggregated | Qwen3-8B, Prefill TP=1 + Decode TP=1, two GPUs total |

### Proposed Solution

Add a dedicated sample directory, organized by engine and deployment mode:

```text
samples/musa-s5000/
├── README.md
├── vllm/
│   ├── colocated.yaml
│   └── pd-disaggregated.yaml
└── sglang/
    ├── colocated.yaml
    └── pd-disaggregated.yaml
```

The exact structure may be adjusted to follow the closest existing AIBrix sample conventions.

#### Common requirements

All samples should:

- use an 8B-or-smaller model that can run on one MTT S5000 GPU;
- request no more than two `mthreads.com/gpu` devices across the entire sample;
- document the required Moore Threads device plugin and MUSA driver;
- document any required `RuntimeClass`, model storage, image-pull credentials, and Hugging Face credentials;
- use the standard AIBrix labels:
  - `model.aibrix.ai/name`
  - `model.aibrix.ai/port`
  - `model.aibrix.ai/engine`
- include health and readiness probes;
- expose the engine metrics endpoint expected by AIBrix;
- document how to send an OpenAI-compatible request through AIBrix Gateway;
- clearly identify vendor-specific images and environment variables;
- state that the configurations are community validated rather than covered by the default AIBrix CI environment.

#### vLLM colocated sample

Provide a single-replica deployment for `Qwen3-8B` or a comparable smaller model:

- one `mthreads.com/gpu` device;
- tensor parallelism `TP=1`;
- `model.aibrix.ai/engine: vllm`;
- ordinary AIBrix Gateway routing.

An initial MUSA-enabled image version is:

```text
registry.mthreads.com/mcconline/inference/vllm:v0.28.0-ph1-5.2.0-torch2.11.0.post1-20260915
```

The final image and model combination must be validated together on MTT S5000.

#### vLLM P/D-disaggregated sample

Provide a minimal two-GPU functional-validation topology, preferably on one node:

- Prefill: one MTT S5000 GPU and `TP=1`;
- Decode: one MTT S5000 GPU and `TP=1`;
- no more than two `mthreads.com/gpu` devices in total;
- vLLM `MooncakeConnector`;
- Mooncake TCP transport with MUSA support;
- `kv_role=kv_producer` for Prefill;
- `kv_role=kv_consumer` for Decode;
- `kv_load_failure_policy=fail` so KV-transfer failures remain visible;
- AIBrix Gateway routing through `routing-strategy: pd`.

The sample should follow the existing AIBrix StormService and P/D role-label conventions instead of introducing an additional router.

#### SGLang colocated sample

Provide a single-replica deployment for `Qwen3-8B` or a comparable smaller model:

- one `mthreads.com/gpu` device;
- tensor parallelism `TP=1`;
- Moore Threads `mthreads` RuntimeClass when required by the cluster;
- `model.aibrix.ai/engine: sglang`;
- a documented model source or local model mount;
- a MUSA-enabled SGLang image and only the environment variables required by that image.

The selected image and model combination must be validated together on MTT S5000.

#### SGLang P/D-disaggregated sample

Provide a minimal two-GPU functional-validation topology, preferably on one node:

- Prefill: one MTT S5000 GPU and `TP=1`;
- Decode: one MTT S5000 GPU and `TP=1`;
- no more than two `mthreads.com/gpu` devices in total;
- SGLang Prefill/Decode disaggregation mode;
- Mooncake TCP transport with MUSA support;
- AIBrix Gateway routing through `routing-strategy: pd`;
- no mandatory RDMA or InfiniBand dependency for the baseline sample;
- non-privileged configuration where supported, using `IPC_LOCK` and an appropriate seccomp profile.

An RDMA-optimized deployment may be documented separately as an optional production tuning path, but it should not be required to run the sample.

### Documentation

The README should include:

- hardware, driver, device-plugin, RuntimeClass, and Kubernetes prerequisites;
- container image access requirements;
- model download or local model-mount instructions;
- deployment commands for all four configurations;
- the per-pod and total GPU requirements;
- readiness verification commands;
- example `/v1/chat/completions` requests;
- AIBrix Gateway configuration and P/D routing examples;
- known limitations and hardware-specific tuning notes.

### Completion Criteria

- [ ] A one-GPU vLLM colocated sample using an 8B-or-smaller model is validated on MTT S5000.
- [ ] A two-GPU vLLM P/D sample with one GPU for Prefill and one for Decode is validated.
- [ ] A one-GPU SGLang colocated sample using an 8B-or-smaller model is validated on MTT S5000.
- [ ] A two-GPU SGLang P/D sample with one GPU for Prefill and one for Decode is validated.
- [ ] No sample requests more than two `mthreads.com/gpu` devices in total.
- [ ] Engine pods contain the required AIBrix discovery labels.
- [ ] Colocated requests work through AIBrix Gateway.
- [ ] P/D requests work through AIBrix Gateway with `routing-strategy: pd`.
- [ ] The baseline P/D samples work without requiring RDMA or InfiniBand.

